files_diff_snippets:
+ resource "aws_vpc_endpoint" "s3" {
+   service_name = var.s3_endpoint_service_name
+   vpc_id = aws_vpc.control_plane.id
+   subnet_ids = compact(concat(var.private_subnet_ids, var.shared_subnet_ids))
+ }

+ resource "aws_vpc_peering_connection" "control_to_customer" {
+   vpc_id = aws_vpc.control_plane.id
+   peer_vpc_id = var.customer_vpc_id
+   auto_accept = false
+ }
